  `slug` VARCHAR(255) NULL,
  `price` DECIMAL(10,2) DEFAULT 0.00,
  `original_price` DECIMAL(10,2) DEFAULT 0.00,
  `category` VARCHAR(255) NULL,
  `brand` VARCHAR(255) NULL,
  `unit` VARCHAR(255) NULL,
  `sku` VARCHAR(255) NULL,
  `images` JSON NULL,
