) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4;

-- Data for table `products` (23 records)
INSERT INTO `products` (`id`, `name`, `slug`, `price`, `original_price`, `category`, `brand`, `unit`, `sku`, `images`, `image_url`, `short_description`, `description`, `badge`, `is_featured`, `variants`, `created_at`) VALUES (1, 'Narikel (Coconut)', 'narikel-coconut', 160, NULL, 'Fresh Fruits', '', '', '', '["data:image/webp;base64,"]', NULL, '<span style="color: rgb(86, 143, 86); font-family: &quot;PT Sans&quot;, sans-serif; font-size: medium;">Product Weight: 900-1100gm Coconut is one of very versatile and indispensable food item for millions of inhabitants in South and South-East Asia. It is one of the most sought-after ingredients in the kitchen since it employed in almost each and every recipe prepared in these parts of the world.&nbsp;</span>', '<span style="color: rgb(86, 143, 86); font-family: &quot;PT Sans&quot;, sans-serif; font-size: medium;">Coconut is a very versatile and indispensable food item for most people under the tropical belt. It is a complete food rich in calories, vitamins, and minerals. A medium-size coconut carrying 400 g edible meat and some 30-150 ml of water may provide almost all the daily-required essential minerals, vitamins, and energy of an average-sized individual. Coconut water is a very refreshing drink to beat tropical summer thirst. The juice is packed with simple sugar, electrolytes, minerals, and bioactive compounds such as cytokinin, and enzymes such as acid phosphatase, catalase, dehydrogenase, peroxidase, polymerases, etc. Altogether, these enzymes aid in digestion and metabolism. It is also a very good source of B-complex vitamins such as folates, riboflavin, niacin, thiamin, and pyridoxine. These vitamins are essential in the sense that body requires them from external sources to replenish. Coconut meat and water contain a very good amount of potassium. 100 g of fresh meat contains 356 mg% or 7.5% of daily required levels of potassium. A full-sized coconut weighs about 1.44 kg (3.2 lb).</span>', NULL, 0, '[]', '2025-12-23T11:03:07.46014+00:00') ON DUPLICATE KEY UPDATE `id`=`id`;
INSERT INTO `products` (`id`, `name`, `slug`, `price`, `original_price`, `category`, `brand`, `unit`, `sku`, `images`, `image_url`, `short_description`, `description`, `badge`, `is_featured`, `variants`, `created_at`) VALUES (21, 'Chicken Liver (Kolija) 500 gm', 'chicken-liver-kolija-500-gm', 139, 199, 'Chicken & Poultry', '', '', '', '["data:image/webp;base64,","https://ik.imagekit.io/vrtbi4wsn/products/WhatsApp_Image_2026-05-11_at_5.08.42_PM_Hpz_382CY.jpeg"]', NULL, '<span style="color: rgb(51, 51, 51); font-family: &quot;Segoe UI&quot;, Helvetica, &quot;Droid Sans&quot;, Arial, &quot;lucida grande&quot;, tahoma, verdana, arial, sans-serif; font-size: 14px;">Fresh, tender chicken liver sourced from broiler chickens. Hygienically cleaned and packed to retain natural taste and nutrition. Perfect for making rich, flavorful dishes such as fried, curry, or sautéed liver recipes. A nutritious choice, high in protein and essential vitamins.</span>', '', NULL, 0, '[]', '2026-01-02T08:23:21.138603+00:00') ON DUPLICATE KEY UPDATE `id`=`id`;
INSERT INTO `products` (`id`, `name`, `slug`, `price`, `original_price`, `category`, `brand`, `unit`, `sku`, `images`, `image_url`, `short_description`, `description`, `badge`, `is_featured`, `variants`, `created_at`) VALUES (5, 'Red Tomato 500 gm', 'red-tomato-500-gm', 75, 85, 'Fresh Vegetables', '', '', '', '["data:image/webp;base64,"]', NULL, '<span style="color: rgb(86, 143, 86); font-family: &quot;PT Sans&quot;, sans-serif; font-size: medium;">Every 500 gm of the product will contain 7-10 pcs of Tomato. The tomato is consumed in diverse ways, including raw, as an ingredient in many dishes, sauces, salads, and drinks. While it is botanically a fruit, it is considered a vegetable for culinary purposes. The fruit is rich in lycopene, which may have beneficial health effects.</span>', '', NULL, 0, '[]', '2025-12-24T04:01:00.758113+00:00') ON DUPLICATE KEY UPDATE `id`=`id`;
INSERT INTO `products` (`id`, `name`, `slug`, `price`, `original_price`, `category`, `brand`, `unit`, `sku`, `images`, `image_url`, `short_description`, `description`, `badge`, `is_featured`, `variants`, `created_at`) VALUES (6, 'Broiler Chicken Skin On 1 kg', 'broiler-chicken-skin-on-1-kg', 280, 285, 'Chicken & Poultry', '', '', '', '["data:image/webp;base64,"]', NULL, '<span style="color: rgb(86, 143, 86); font-family: &quot;PT Sans&quot;, sans-serif; font-size: medium;">Before processing this product\'s live weight was 1.5-1.55 kg. Broiler chickens are raised primarily for meat rather than to lay eggs. These poultry are often white and are bred to be large and very healthy, often with more breast meat for the consumer market. Broiler chicken breeds grow very fast and offer good value in terms of protein and calories.</span>', '', NULL, 0, '[]', '2025-12-24T04:01:41.185906+00:00') ON DUPLICATE KEY UPDATE `id`=`id`;
INSERT INTO `products` (`id`, `name`, `slug`, `price`, `original_price`, `category`, `brand`, `unit`, `sku`, `images`, `image_url`, `short_description`, `description`, `badge`, `is_featured`, `variants`, `created_at`) VALUES (7, 'Broiler Chicken Skin Off 1 kg', 'broiler-chicken-skin-off-1-kg', 300, 310, 'Chicken & Poultry', '', '', '', '["data:image/webp;base64,"]', NULL, '<span style="color: rgb(86, 143, 86); font-family: &quot;PT Sans&quot;, sans-serif; font-size: medium;">Before processing this product\'s live weight was 1.7 kg. Broiler chickens are raised primarily for meat rather than to lay eggs. These poultry are often white and are bred to be large and very healthy, often with more breast meat for the consumer market. Broiler chicken breeds grow very fast and offer good value in terms of protein and calories.</span>', '', NULL, 0, '[]', '2025-12-24T04:02:14.446251+00:00') ON DUPLICATE KEY UPDATE `id`=`id`;
INSERT INTO `products` (`id`, `name`, `slug`, `price`, `original_price`, `category`, `brand`, `unit`, `sku`, `images`, `image_url`, `short_description`, `description`, `badge`, `is_featured`, `variants`, `created_at`) VALUES (8, 'Koi Fish Processed 1 kg', 'koi-fish-processed-1-kg', 320, 410, 'Frozen Fish', '', '', '', '["data:image/webp;base64,"]', NULL, '<span style="color: rgb(86, 143, 86); font-family: &quot;PT Sans&quot;, sans-serif; font-size: medium;">Before processing this product live weight was 1.3 - 1.35 kg and the product quantity around 10-12 pcs. Anabas cobojius, the Gangetic koi, popularly known as Koi in Bengali is a species of climbing gourami native to Bangladesh and India, where it occurs in many types of standing water bodies. This species reaches a total length of 30 cm (12 in) and is carnivorous, feeding on water invertebrates and their larvae. In Khulna &amp; Jessore areas best quality Koi fish is available.</span>', '', NULL, 0, '[]', '2025-12-24T04:02:43.905194+00:00') ON DUPLICATE KEY UPDATE `id`=`id`;
INSERT INTO `products` (`id`, `name`, `slug`, `price`, `original_price`, `category`, `brand`, `unit`, `sku`, `images`, `image_url`, `short_description`, `description`, `badge`, `is_featured`, `variants`, `created_at`) VALUES (9, 'Whole Hilsha Fish (Asto Ilish) 1.3 kg', 'whole-hilsha-fish-asto-ilish-13-kg', 3500, 3900, 'Frozen Fish', '', '', '', '["data:image/webp;base64,"]', NULL, '<span style="color: rgb(86, 143, 86); font-family: &quot;PT Sans&quot;, sans-serif; font-size: medium;">This fish is prepared in varity of way like it can be smoked, fried, steamed, baked, prepared with mustard seed paste, curd, brinjal (eggplant). Some common hilsa menus are Fried hilsa, Khichuri-Ilish, Sorshe Ilish, Panta Ilish,Vapa Ilish etc. It has cultural value in Bangali’s life. It is an obvious food in many cultural festival like Pahela Boishakh, Saraswati Puja.</span>', '', NULL, 0, '[]', '2025-12-24T04:04:06.819207+00:00') ON DUPLICATE KEY UPDATE `id`=`id`;
INSERT INTO `products` (`id`, `name`, `slug`, `price`, `original_price`, `category`, `brand`, `unit`, `sku`, `images`, `image_url`, `short_description`, `description`, `badge`, `is_featured`, `variants`, `created_at`) VALUES (2, 'Livon Hair Serum 50/100/200/250 ml', 'livon-hair-serum-50100200250-ml', 249, 300, 'Hair Care', 'Livon', '', '', '["data:image/webp;base64,"]', NULL, '<div><ul><li>Product Benefits: Soft &amp; Silky Hair, Boosts Shine, Anti Frizz</li><li>Item Form: Serum</li><li>Material Type Free: Paraben, Silicone Free</li><li>Scent: Argan</li><li>Hair Type: All Hair Types</li><li>Liquid Volume: 50 ml</li><li>Special Feature: Contains Argan &amp; Vitamin E</li></ul></div>', '', NULL, 0, '[{"id":"sbmlwqh4a","sku":"PROD-0","image":"data:image/webp;base64,","price":249,"stock":100,"originalPrice":300,"attributeValues":{"Size":"50ml"}},{"id":"oupetc6mc","sku":"PROD-1","image":"data:image/webp;base64,","price":279,"stock":100,"originalPrice":330,"attributeValues":{"Size":"100ml"}},{"id":"cq87fkebt","sku":"PROD-2","image":"data:image/webp;base64,","price":289,"stock":100,"originalPrice":370,"attributeValues":{"Size":"200ml"}},{"id":"yyo6umz6g","sku":"PROD-3","image":"data:image/webp;base64,","price":299,"stock":100,"originalPrice":400,"attributeValues":{"Size":"250ml"}}]', '2025-12-23T11:47:23.105155+00:00') ON DUPLICATE KEY UPDATE `id`=`id`;
INSERT INTO `products` (`id`, `name`, `slug`, `price`, `original_price`, `category`, `brand`, `unit`, `sku`, `images`, `image_url`, `short_description`, `description`, `badge`, `is_featured`, `variants`, `created_at`) VALUES (4, 'Shagor Kola (Banana Sagor)', 'shagor-kola-banana-sagor', 45, 50, 'Fresh Fruits', '', '', '', '["data:image/webp;base64,","data:image/png;base64,"]', NULL, '<span style="color: rgb(86, 143, 86); font-family: &quot;PT Sans&quot;, sans-serif; font-size: medium;">Shagor Bananas are one of the most popular fruits in the world. They\'re full of important nutrients. It contains high amounts of vitamins C, and B, as well as magnesium, potassium, folate, and antioxidants. It also contains some fiber and protein. Can be eaten both raw and ripe. Ripe bananas are sweet. Sagor bananas are usually long in size and ripen very quickly.</span>', '', NULL, 0, '[]', '2025-12-24T04:00:27.985394+00:00') ON DUPLICATE KEY UPDATE `id`=`id`;
INSERT INTO `products` (`id`, `name`, `slug`, `price`, `original_price`, `category`, `brand`, `unit`, `sku`, `images`, `image_url`, `short_description`, `description`, `badge`, `is_featured`, `variants`, `created_at`) VALUES (3, 'Lal Alu (Red Potato Cardinal) 1kg', 'lal-alu-red-potato-cardinal-1kg', 29, NULL, 'Fresh Vegetables', '', '', '', '["data:image/webp;base64,"]', NULL, '<span style="color: rgb(86, 143, 86); font-family: &quot;PT Sans&quot;, sans-serif; font-size: medium;">15-20 pcs</span><div><span style="color: rgb(86, 143, 86); font-family: &quot;PT Sans&quot;, sans-serif; font-size: medium;">Cardinal Potato is a variety of potato that is known for its distinct red skin and smooth, white flesh. The skin of Cardinal potatoes is bright red, and it has an appealing smooth texture, making it easy to peel if desired.</span></div>', '<span style="color: rgb(86, 143, 86); font-family: &quot;PT Sans&quot;, sans-serif; font-size: medium;">The flesh inside is firm, waxy, and white, with a smooth and creamy texture when cooked. In terms of taste, Cardinal potatoes have a mild, slightly earthy flavor that is not overly strong. This makes them a versatile ingredient in various dishes, including salads, casseroles, and potato side dishes. Nutritionally, Cardinal potatoes are a good source of complex carbohydrates, fiber, and essential vitamins like Vitamin C and B6. They provide energy, support digestion, and help in boosting the immune system.</span>', NULL, 0, '[]', '2025-12-24T03:59:53.051981+00:00') ON DUPLICATE KEY UPDATE `id`=`id`;
INSERT INTO `products` (`id`, `name`, `slug`, `price`, `original_price`, `category`, `brand`, `unit`, `sku`, `images`, `image_url`, `short_description`, `description`, `badge`, `is_featured`, `variants`, `created_at`) VALUES (10, 'Parachute Advanced Aloe Vera Hair Oil 250 ml 2 pcs', 'parachute-advanced-aloe-vera-hair-oil-250-ml-2-pcs', 600, 640, 'Hair Care', 'Parachute', '', '', '["data:image/webp;base64,"]', NULL, '<ul><li>A<span style="color: rgb(86, 143, 86); font-family: &quot;PT Sans&quot;, sans-serif; font-size: medium;">dvansed Product Benefits: Strong, Soft, Silky Hair</span></li><li><span style="color: rgb(86, 143, 86); font-family: &quot;PT Sans&quot;, sans-serif; font-size: medium;">Item Form: Oil Material</span></li><li><span style="color: rgb(86, 143, 86); font-family: &quot;PT Sans&quot;, sans-serif; font-size: medium;">Type Free: Sulphate Free</span></li><li><span style="color: rgb(86, 143, 86); font-family: &quot;PT Sans&quot;, sans-serif; font-size: medium;">Scent: Coconut</span></li><li><span style="color: rgb(86, 143, 86); font-family: &quot;PT Sans&quot;, sans-serif; font-size: medium;">Hair Type: All Hair Types</span></li><li><span style="color: rgb(86, 143, 86); font-family: &quot;PT Sans&quot;, sans-serif; font-size: medium;">Liquid Volume: 500 ml</span></li><li><span style="color: rgb(86, 143, 86); font-family: &quot;PT Sans&quot;, sans-serif; font-size: medium;">Special Feature: Contains Aloe Vera &amp; Coconut</span></li></ul>', '<ul><li><span style="color: rgb(86, 143, 86); font-family: &quot;PT Sans&quot;, sans-serif; font-size: medium;">Enriched with Aloe Vera Extracts: Infused with the goodness of pure coconut oil and aloe vera extracts, this hair oil nourishes both the hair and scalp effectively. Aloe Vera is known for its moisturizing and soothing properties, which help to hydrate the scalp and promote healthy hair growth.</span></li><li><span style="color: rgb(86, 143, 86); font-family: &quot;PT Sans&quot;, sans-serif; font-size: medium;">Non-Sticky and Lightweight: The non-sticky formula of this coconut and aloe vera-enriched hair oil ensures deep nourishment without leaving any greasy residue. It effectively reduces dandruff and repairs dull and damaged hair, leaving them feeling light and revitalized.</span></li><li><span style="color: rgb(86, 143, 86); font-family: &quot;PT Sans&quot;, sans-serif; font-size: medium;">Promise of Purity and Quality: Made from natural coconut oil, ensuring purity and quality in every single drop. The oil is free from any impurities, making it safe and gentle for regular use on all hair types.</span></li><li><span style="color: rgb(86, 143, 86); font-family: &quot;PT Sans&quot;, sans-serif; font-size: medium;">Makes Hair Softer, Stronger, and Silkier: The combination of pure coconut oil and aloe vera extracts provides quality nourishment to the hair, resulting in stronger, softer, and silkier locks.</span></li><li><span style="color: rgb(86, 143, 86); font-family: &quot;PT Sans&quot;, sans-serif; font-size: medium;">Goodness of Coconut Oil: Coconut oil penetrates 10X deeper into the hair and scalp, strengthening them from the core and promoting overall hair health.</span></li><li><span style="color: rgb(86, 143, 86); font-family: &quot;PT Sans&quot;, sans-serif; font-size: medium;">Suitable for All Hair Types: Whether you have straight, curly, thin, thick, fine, or textured hair, this is suitable for all hair types</span></li></ul><span style="color: rgb(86, 143, 86); font-family: &quot;PT Sans&quot;, sans-serif; font-size: medium;"><b>How To Use:</b> This product is for external use only. To properly use, take a few drops of the hair into your hands. Rub your palms together and gently massage into the hair. Use Parachute Advanced Aloe Vera at least thrice a week for best results.</span>', NULL, 0, '[]', '2025-12-24T04:08:24.363233+00:00') ON DUPLICATE KEY UPDATE `id`=`id`;
INSERT INTO `products` (`id`, `name`, `slug`, `price`, `original_price`, `category`, `brand`, `unit`, `sku`, `images`, `image_url`, `short_description`, `description`, `badge`, `is_featured`, `variants`, `created_at`) VALUES (11, 'Trix Dish Washing Bar Lemon 300 gm', 'trix-dish-washing-bar-lemon-300-gm', 40, NULL, 'Dishwashing Supplies', 'Trix', '', '', '["data:image/webp;base64,"]', NULL, '<ul><li><span style="color: rgb(86, 143, 86); font-family: &quot;PT Sans&quot;, sans-serif; font-size: medium;">Trix Dishwashing Bar: gives you the fastest and shiniest scratch-free dishwashing solution</span></li><li><span style="color: rgb(86, 143, 86); font-family: &quot;PT Sans&quot;, sans-serif; font-size: medium;">Sparkling Clean: effortlessly cleans dishes, utensils &amp; tableware and leaves them sparkling</span></li><li><span style="color: rgb(86, 143, 86); font-family: &quot;PT Sans&quot;, sans-serif; font-size: medium;">Tough on grease &amp; food stains but soft on hands</span></li><li><span style="color: rgb(86, 143, 86); font-family: &quot;PT Sans&quot;, sans-serif; font-size: medium;">Power Thick Foam: removes grease stains and unseen food residue from the dishes</span></li><li><span style="color: rgb(86, 143, 86); font-family: &quot;PT Sans&quot;, sans-serif; font-size: medium;">Refreshing Lemon Fragrance: it provides an amazing cleaning experience with a refreshing lemon fragrance during dishwashing</span></li><li><span style="color: rgb(86, 143, 86); font-family: &quot;PT Sans&quot;, sans-serif; font-size: medium;">Recommended for cleaning all types of utensils like stainless steel, ceramic, non-stick ware, glass, etc</span></li><li><span style="color: rgb(86, 143, 86); font-family: &quot;PT Sans&quot;, sans-serif; font-size: medium;">● Available Variant: Lemon</span></li></ul>', '', NULL, 0, '[]', '2025-12-31T10:14:07.135726+00:00') ON DUPLICATE KEY UPDATE `id`=`id`;
INSERT INTO `products` (`id`, `name`, `slug`, `price`, `original_price`, `category`, `brand`, `unit`, `sku`, `images`, `image_url`, `short_description`, `description`, `badge`, `is_featured`, `variants`, `created_at`) VALUES (12, 'Vim Dishwashing Bar', 'vim-dishwashing-bar', 15, NULL, 'Dishwashing Supplies', 'Vim', '', '', '["data:image/webp;base64,"]', NULL, '<span style="color: rgb(86, 143, 86); font-family: &quot;PT Sans&quot;, sans-serif; font-size: medium;">With the power of 100 lemons, Vim Bar helps to clean tough grease the fastest. It gives you a pleasant cleaning experience with its refreshing lemon fragrance. It removes stains easily. It is tough on stains and gentle on your hands. Just take a little bit of Vim Bar on your scrubber and clean your cooking vessels.</span>', '', NULL, 0, '[]', '2025-12-31T10:14:46.36345+00:00') ON DUPLICATE KEY UPDATE `id`=`id`;
INSERT INTO `products` (`id`, `name`, `slug`, `price`, `original_price`, `category`, `brand`, `unit`, `sku`, `images`, `image_url`, `short_description`, `description`, `badge`, `is_featured`, `variants`, `created_at`) VALUES (13, 'Fast Wash Detergent Powder 1 kg', 'fast-wash-detergent-powder-1-kg', 180, NULL, 'Laundry', 'Fast Wash', '', '', '["data:image/webp;base64,"]', NULL, '<span style="color: rgb(86, 143, 86); font-family: &quot;PT Sans&quot;, sans-serif; font-size: medium;">Fast Wash Detergent Powder is formulated to provide a powerful and effective cleaning experience. It\'s advanced formula penetrates fabric fibers to remove dirt, stains, and odors, leaving clothes fresh and clean. Suitable for both hand wash and machine wash, it ensures that every wash is thorough yet gentle on fabric. With a refreshing fragrance, this detergent powder keeps clothes smelling great all day.</span>', '', NULL, 0, '[]', '2025-12-31T10:20:15.392955+00:00') ON DUPLICATE KEY UPDATE `id`=`id`;
INSERT INTO `products` (`id`, `name`, `slug`, `price`, `original_price`, `category`, `brand`, `unit`, `sku`, `images`, `image_url`, `short_description`, `description`, `badge`, `is_featured`, `variants`, `created_at`) VALUES (14, 'Rin Advanced Detergent Powder 1kg', 'rin-advanced-detergent-powder-1kg', 185, NULL, 'Laundry', 'Rin', '', '', '["data:image/webp;base64,"]', NULL, '<span style="color: rgb(86, 143, 86); font-family: &quot;PT Sans&quot;, sans-serif; font-size: medium;">Rin Washing Powder removes dirt from deep within the cloth fiber, thereby removing dullness from your clothes. Rin Washing Powder comes with Bright Clean Technology, making your clothes look \'Bright like new\'.&nbsp;</span>', '<span style="color: rgb(86, 143, 86); font-family: &quot;PT Sans&quot;, sans-serif; font-size: medium;">Use 1 or 2 scoops of Rin for a bucket wash &amp; 2 or 3 scoops of Rin for machine wash. Your Rin Washing Powder is suitable for whites as well as coloured clothes. Keep your clothes shining \'Bright like new\' with Rin Washing Powder. Rin believes that everyone is talented and it is the lack of opportunities that stand in the way. Rin believes that nothing should come in the way of your progress. Each one of you has the talent and deserves an opportunity to shine. Rin promises to make your clothes whiter and brighter, so that you can get the confidence to stride ahead on your journey to progress. Rin enables the people it serves, shine by giving them brighter cleaner clothes. The brand essence “Dress to Progress” captures the idea that bright clothes can help radiate confidence and open doors to progress.</span>', NULL, 0, '[]', '2025-12-31T10:20:53.014316+00:00') ON DUPLICATE KEY UPDATE `id`=`id`;
