INSERT INTO `products` (`id`, `name`, `slug`, `price`, `original_price`, `category`, `brand`, `unit`, `sku`, `images`, `image_url`, `short_description`, `description`, `badge`, `is_featured`, `variants`, `created_at`) VALUES (16, 'Sobuj Angur (Green Grapes) Imported ± 12 gm', 'sobuj-angur-green-grapes-imported-12-gm', 159, 189, 'Fresh Fruits', '', '', '', '["data:image/webp;base64,"]', NULL, '<span style="color: rgb(51, 51, 51); font-family: &quot;Segoe UI&quot;, Helvetica, &quot;Droid Sans&quot;, Arial, &quot;lucida grande&quot;, tahoma, verdana, arial, sans-serif; font-size: 14px;">Australian Green Grapes are crisp, juicy, and naturally sweet table grapes grown in Australia’s sunny vineyards. They have a refreshing flavor, smooth green skin, and are rich in vitamins, antioxidants, and hydration — they may also offer benefits such as protecting against cell damage, supporting heart health, and aiding in the prevention of cance cell growth.</span>', '', NULL, 0, '[]', '2026-01-02T08:17:10.824964+00:00') ON DUPLICATE KEY UPDATE `id`=`id`;
INSERT INTO `products` (`id`, `name`, `slug`, `price`, `original_price`, `category`, `brand`, `unit`, `sku`, `images`, `image_url`, `short_description`, `description`, `badge`, `is_featured`, `variants`, `created_at`) VALUES (17, 'Beef Bone In 1kg', 'beef-bone-in-1kg', 779, 799, 'Meat', '', '', '', '["data:image/webp;base64,"]', NULL, '<p data-reactid=".wx47ic16rm.$3161.0.1.0.1.5.$line-0" style="-webkit-tap-highlight-color: transparent; margin-bottom: 0px; padding: 0px; color: rgb(51, 51, 51); font-size: 14px; font-family: &quot;Segoe UI&quot;, Helvetica, &quot;Droid Sans&quot;, Arial, &quot;lucida grande&quot;, tahoma, verdana, arial, sans-serif;">Product\'s Qty: 23-24 pcs</p><p data-reactid=".wx47ic16rm.$3161.0.1.0.1.5.$line-1" style="-webkit-tap-highlight-color: transparent; margin-top: 0px; margin-bottom: 0px; padding: 0px; color: rgb(51, 51, 51); font-size: 14px; font-family: &quot;Segoe UI&quot;, Helvetica, &quot;Droid Sans&quot;, Arial, &quot;lucida grande&quot;, tahoma, verdana, arial, sans-serif;">Beef Bones. Also Known As: Cent Cut Bones; Femur Bones; Knuckle Bones; Marrow Bones. Strong beef flavor. Roast before adding to a broth. Butcher\'s Note.</p>', '', NULL, 0, '[]', '2026-01-02T08:19:27.801252+00:00') ON DUPLICATE KEY UPDATE `id`=`id`;
