INSERT INTO `pages` (`id`, `title`, `slug`, `content`, `is_published`, `created_at`) VALUES (1, 'About Us', 'about-us', '[{"id":"9720bc85-2007-4a64-bc5e-19754d5020a3","type":"hero_section","data":{"title":"Our Mission is Freshness","description":"Providing high-quality, organic, and farm-fresh groceries delivered straight to your doorstep since 2023.","background_url":"https://images.unsplash.com/photo-1542838132-92c53300491e?auto=format&fit=crop&q=80&w=1600"}},{"id":"0888d3f9-88c1-4dea-b77d-2afbcacd5699","type":"story_section","data":{"badge":"Our Story","title":"From Local Farm to","description":"SMart began with a simple observation: getting truly fresh, high-quality groceries in the city was harder than it should be. We started as a small local initiative connecting three organic farms with families in our neighborhood.\\n\\nToday, we have grown into a premium grocery destination, partnering with over 50 local producers to bring you the finest selection of fruits, vegetables, meats, and daily essentials. Our commitment to quality remains as strong as the day we started.","image_url":"https://dnaziaddhwmqalwrdgex.supabase.co/storage/v1/object/public/product-images/about-us.png","title2":"Your Family Table"}},{"id":"6f9d55d2-f1fd-4154-9767-653959f837e3","type":"values_grid","data":{"title":"The Values We Live By","subtitle":"We generally nourish communities through our core principles.","items":[{"icon":"Heart","title":"Quality First","description":"Every item is hand-picked and inspected for peak freshness before it reaches your door."},{"icon":"User","title":"Community Driven","description":"We support local farmers and producers, ensuring fair trade and sustainable growth."},{"icon":"Zap","title":"Efficiency","description":"Our logistics chain is optimized to reduce delivery times and minimize environmental impact."},{"icon":"ShieldCheck","title":"Food Safety","description":"Strict hygiene protocols and cold-chain management from storage to delivery."},{"icon":"Droplets","title":"Transparency","description":"Full traceability of where your food comes from and how it was produced."},{"icon":"ShoppingBasket","title":"Convenience","description":"Building a seamless shopping experience that fits perfectly into your busy lifestyle."}]}},{"id":"3aa93c7d-f54d-4688-8162-1e87c3c1bc8e","type":"cta_section","data":{"title":"Fresh Groceries are\\nJust a Click Away","subtitle":"Join thousands of families who trust SMart for their daily nutrition.","button1_text":"Browse Products","button1_link":"/products","button2_text":"Contact Support","button2_link":"/contact"}}]', 1, '2025-12-27T05:06:36.742387+00:00') ON DUPLICATE KEY UPDATE `id`=`id`;
INSERT INTO `pages` (`id`, `title`, `slug`, `content`, `is_published`, `created_at`) VALUES (2, 'Contact Us', 'contact-us', '[{"id":"b8256ca3-8260-4fd5-98c0-12be74c1dddd","type":"contact_section","data":{"title":"Contact Information","subtitle":"We\'d love to hear from you! Reach out to us with any questions.","items":[{"icon":"Mail","label":"E-mail Address","value":"support@smart.com"},{"icon":"Phone","label":"Phone Number","value":"+880123456789"},{"icon":"MapPin","label":"Address","value":"Dhaka, Bangladesh"},{"icon":"CheckCircle","label":"Facebook","value":"SmartGrocery"}]}},{"id":"2ae10024-2b8e-4741-9c96-637c2cc6d9f4","type":"faq_contact_section","data":{"title":"People usually ask these","formTitle":"Send Us a Message","faqs":[{"question":"What is your return policy?","answer":"We have a flexible return policy. If you are not satisfied with your purchase, you may be eligible for a return within the specified return period."},{"question":"What are your shipping options and delivery times?","answer":"We offer standard and express shipping options. Delivery times vary based on your location."},{"question":"What payment methods do you accept?","answer":"We accept all major credit cards, PayPal, and cash on delivery."}]}}]', 1, '2025-12-28T08:33:43.841641+00:00') ON DUPLICATE KEY UPDATE `id`=`id`;

