-- --------------------------------------------------------
-- Table structure for `blog_posts`
-- --------------------------------------------------------
CREATE TABLE IF NOT EXISTS `blog_posts` (
  `id` BIGINT AUTO_INCREMENT PRIMARY KEY,
  `title` VARCHAR(255) NULL,
  `slug` VARCHAR(255) NULL,
  `excerpt` TEXT NULL,
  `content` LONGTEXT NULL,
  `author` VARCHAR(255) NULL,
  `image_url` TEXT NULL,
  `tags` JSON NULL,
  `created_at` DATETIME NULL
) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4;

-- Data for table `blog_posts` (3 records)
INSERT INTO `blog_posts` (`id`, `title`, `slug`, `excerpt`, `content`, `author`, `image_url`, `tags`, `created_at`) VALUES (3, 'Why Online Grocery Shopping Is the Smart Choice for Modern Families', 'why-online-grocery-shopping-is-the-smart-choice-for-modern-families', 'In today’s fast-paced lifestyle, time has become one of our most valuable resources. Online grocery shopping is transforming how families manage their daily needs by offering convenience, efficiency, and smarter choices.', '<p data-start="569" data-end="789">In today’s fast-paced lifestyle, time has become one of our most valuable resources. Online grocery shopping is transforming how families manage their daily needs by offering convenience, efficiency, and smarter choices.</p>
<h3 data-start="791" data-end="818">⏱️ Save Time &amp; Effort</h3>
<p data-start="819" data-end="995">No more traffic jams, long checkout lines, or crowded aisles. With an online grocery platform, you can shop anytime—early morning or late night—right from your phone or laptop.</p>
<h3 data-start="997" data-end="1023">🏠 Doorstep Delivery</h3>
<p data-start="1024" data-end="1194">Fresh vegetables, daily essentials, snacks, and household items are delivered straight to your home. This means less stress and more time for family, work, or relaxation.</p>
<h3 data-start="1196" data-end="1241">💸 Better Deals &amp; Easy Price Comparison</h3>
<p data-start="1242" data-end="1409">Online grocery stores often provide exclusive discounts, bundle offers, and loyalty rewards. Comparing prices is quick and transparent, helping you stay within budget.</p>
<p data-start="1411" data-end="1495">Online grocery shopping isn’t just a convenience—it’s a smarter, modern way to shop.</p>', 'Smart Grocery', 'https://dnaziaddhwmqalwrdgex.supabase.co/storage/v1/object/public/product-images/blog-0.5999990261179802.jpg', '[]', '2025-12-29T09:56:55.730063+00:00') ON DUPLICATE KEY UPDATE `id`=`id`;
INSERT INTO `blog_posts` (`id`, `title`, `slug`, `excerpt`, `content`, `author`, `image_url`, `tags`, `created_at`) VALUES (5, 'Top Grocery Items You Should Always Buy Online', 'top-grocery-items-you-should-always-buy-online', 'Not all grocery items are equal—but some are perfect for online shopping due to convenience and availability.', '<p data-start="2967" data-end="3076">Not all grocery items are equal—but some are perfect for online shopping due to convenience and availability.</p>
<h3 data-start="3078" data-end="3103">🧺 Daily Essentials</h3>
<p data-start="3104" data-end="3245">Rice, flour, oil, sugar, lentils, and spices are ideal for online purchase. They’re easy to store, frequently used, and often cheaper online.</p>
<h3 data-start="3247" data-end="3276">🥛 Dairy &amp; Frozen Items</h3>
<p data-start="3277" data-end="3379">Milk, butter, frozen snacks, and ice cream are now safely delivered using modern cold-chain logistics.</p>
<h3 data-start="3381" data-end="3419">🧼 Household &amp; Cleaning Products</h3>
<p data-start="3420" data-end="3545">Detergents, dishwashing liquids, tissues, and cleaners are bulky and heavy—making online delivery the most convenient option.</p>
<h3 data-start="3547" data-end="3574">🍫 Snacks &amp; Beverages</h3>
<p data-start="3575" data-end="3680">Chips, chocolates, juices, and soft drinks are often available in exclusive online packs and combo deals.</p>
<p data-start="3682" data-end="3785">Buying these items online helps you save time, money, and effort—while keeping your home fully stocked.</p>', 'Smart Grocery', 'https://dnaziaddhwmqalwrdgex.supabase.co/storage/v1/object/public/product-images/blog-0.5403685831444175.jpg', '[]', '2025-12-29T10:08:15.287309+00:00') ON DUPLICATE KEY UPDATE `id`=`id`;
INSERT INTO `blog_posts` (`id`, `title`, `slug`, `excerpt`, `content`, `author`, `image_url`, `tags`, `created_at`) VALUES (4, 'How to Choose Fresh & Healthy Groceries When Shopping Online', 'how-to-choose-fresh-healthy-groceries-when-shopping-online', 'Many shoppers wonder: Can I really get fresh groceries online? The answer is yes—if you know what to look for.', '<p data-start="1788" data-end="1900">Many shoppers wonder: <em data-start="1810" data-end="1852">Can I really get fresh groceries online?</em> The answer is yes—if you know what to look for.</p>
<h3 data-start="1902" data-end="1947">🥬 Check Product Descriptions Carefully</h3>
<p data-start="1948" data-end="2086">Quality online grocery platforms provide detailed descriptions, source information, and freshness indicators for produce, meat, and dairy.</p>
<h3 data-start="2088" data-end="2118">⭐ Read Reviews &amp; Ratings</h3>
<p data-start="2119" data-end="2249">Customer reviews are your best guide. They help you understand product quality, freshness, and packaging before making a purchase.</p>
<h3 data-start="2251" data-end="2295">📅 Look for Fresh Stock &amp; Expiry Dates</h3>
<p data-start="2296" data-end="2419">Reputable grocery e-commerce websites clearly display expiry dates and ensure regular stock rotation to maintain freshness.</p>
<h3 data-start="2421" data-end="2455">🚚 Reliable Delivery Matters</h3>
<p data-start="2456" data-end="2590">Fast and temperature-controlled delivery plays a crucial role in maintaining food quality, especially for frozen and perishable items.</p>
<p data-start="2592" data-end="2682">Healthy grocery shopping online is easy when you shop smart and choose a trusted platform.</p>', 'Smart Grocery', 'https://dnaziaddhwmqalwrdgex.supabase.co/storage/v1/object/public/product-images/blog-0.36244797825335917.jpg', '[]', '2025-12-29T10:07:45.617556+00:00') ON DUPLICATE KEY UPDATE `id`=`id`;

SET FOREIGN_KEY_CHECKS = 1;
